/// <summary>
/// Extension class for <c>VendSumForPaym</c>
/// MPJ_30779_MetpayPaymentPlus
/// </summary>
[ExtensionOf(classstr(VendSumForPaym))]
final class METVendSumForPaym_Extension
{
}

Method.Source:
    /// <summary>
    /// Update query
    /// </summary>
    protected void updateQuery()
    {
        QueryBuildRange metQbr;
        next updateQuery();

        metQbr  =   queryRun.query().dataSourceTable(tableNum(LedgerJournalTrans)).rangeField(fieldNum(LedgerJournalTrans, PaymentStatus));
        metQbr.value(strFmt('%1,%2,%3,%4,%5', CustVendPaymStatus::None,
                CustVendPaymStatus::Rejected,
                CustVendPaymStatus::METWithdraw,
                CustVendPaymStatus::METResend,
                CustVendPaymStatus::METDueDate));
        metQbr.status(RangeStatus::Open);
    }
